package id.unnes.bemfhunnes.auth; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService auth;public AuthController(AuthService a){auth=a;} @PostMapping("/login") public ResponseEntity<?> login(@RequestBody Map<String,String> body)throws Exception{try{return ResponseEntity.ok(auth.login(body.getOrDefault("email","").trim(),body.getOrDefault("password","")));}catch(IllegalArgumentException e){return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("message",e.getMessage()));}} @GetMapping("/me") public Map<String,Object> me(HttpServletRequest r){return Map.of("user",auth.user(r));}}
